Given a Binary Tree of n nodes, the task is to find all the nodes that don't have any siblings. Return a list of integers containing all the nodes that don't have a sibling in sorted order (Increasing).Two nodes are said to be siblings if they are present at the same level, and their parents are the same.Example:Input:  Output: 4 5 6Input:  Output: 10 20Try It YourselfTable of Content[Expeacted Approach - 1] Using Recursion - O(nlogn) Time and O(n) Space[Expected Approach - 2] Using Queue - O(nlogn) Time and O(n) Space[Expeacted Approach - 1] Using Recursion - O(nlogn) Time and O(n) SpaceThe idea is to recursively traverse the binary tree. For each node, if both its child nodes exists, then process both the left and right subtrees. If only left subtree exists, then append its value to the result and process it recursively. If only right subtree exists, then append its value to the result, and process it recursively. Finally sort the resultant array and return it.Below is the implementation of the above approach:
            C++

    // C++ Program to find nodes with no 
// siblings in a given binary tree
#include <bits/stdc++.h>
using namespace std;

class Node {
    public:
        Node *left, *right;
        int data;
        Node(int x) {
            data = x;
            left = nullptr;
            right = nullptr;
        }
};

void noSiblingRecur(Node* node, vector<int> &ans) {

    // base case
    if (node == nullptr) return;

    // If this is an internal node, recur for left
    // and right subtrees
    if (node->left != nullptr && node->right != nullptr) {
        noSiblingRecur(node->left, ans);
        noSiblingRecur(node->right, ans);
    }

    // If only left child exists, then
    // append it to result and recur.
    else if (node->left != nullptr) {
        ans.push_back(node->left->data);
        noSiblingRecur(node->left, ans);
    }

    // If only right child exists, then
    // append it to result and recur.
    else if (node->right != nullptr) {
        ans.push_back(node->right->data);
        noSiblingRecur(node->right, ans);
    }
}

vector<int> noSibling(Node* node) {

    vector<int> ans;

    noSiblingRecur(node, ans);

    // if there are 0 nodes
    // without any siblings
    if (ans.empty())
        ans.push_back(-1);

    // else sort the result
    else
        sort(ans.begin(), ans.end());

    return ans;
}

void printList(vector<int> v) {
    int n = v.size();
    for (int i=0; i<n; i++) {
        cout << v[i] << " ";
    }
    cout<<endl;
}

int main() {

    // Create a hard coded binary tree
    //        1
    //      /   \
    //     2     3            
    //      \   /
    //      4  5     
    //        /
    //       6
    Node *root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->right = new Node(4);
    root->right->left = new Node(5);
    root->right->left->left = new Node(6);

    vector<int> ans = noSibling(root);
    printList(ans);

    return 0;
}


